// Voxel-PSX model remap (docs/ART_VOXEL_PSX.md section 4.2).
// One URL resolver, used by Assets.load / has / get / clips / instantiate, so no caller changes per asset.
// voxelIndex.ts and voxelReplace.ts are generated by `node tools/voxel/build_remap.mjs` (run it after every change under
// public/assets/models/voxel/; `--check` exits 1 when they are stale).

import { SETTINGS_KEY } from './Settings';
import { VOXEL_INDEX } from './voxelIndex';
import { VOXEL_REPLACE } from './voxelReplace';

export const VOXEL_ROOT = '/assets/models/voxel/';
const SOURCE_ROOT = '/assets/models/';

let enabled: boolean | null = null;

/**
 * Voxel models on for this page load. `?voxel=0` / `?voxel=1` win over the stored setting (A/B checks); otherwise the
 * stored `voxelModels` flag (default on). Read once: the asset cache lives as long as the page, so a changed setting
 * takes effect on the next reload.
 */
export function voxelOn(): boolean {
  if (enabled !== null) return enabled;
  let on = true;
  try {
    const q = new URLSearchParams(window.location.search).get('voxel');
    if (q === '0') on = false;
    else if (q === '1') on = true;
    else on = (JSON.parse(localStorage.getItem(SETTINGS_KEY) || '{}') as { voxelModels?: unknown }).voxelModels !== false;
  } catch {
    on = true; // no window / storage (tests, previews): the default is on
  }
  enabled = on;
  return on;
}

/**
 * The URL to fetch for a requested model. Returns `url` unchanged when voxel models are off, when it is not a GLB/glTF,
 * when it is already a voxel URL, or when no converted file exists (per-file fallback to the original).
 * VOXEL_REPLACE (trees, rocks, bushes ... from WP5) wins over the mirrored path.
 */
export function resolveModelUrl(url: string, on: boolean = voxelOn()): string {
  if (!on || !/\.(glb|gltf)$/i.test(url) || url.startsWith(VOXEL_ROOT)) return url;
  const rep = VOXEL_REPLACE[url];
  if (rep) return rep;
  if (!url.startsWith(SOURCE_ROOT)) return url;
  const v = VOXEL_ROOT + url.slice(SOURCE_ROOT.length).replace(/\.gltf$/i, '.glb');
  return VOXEL_INDEX.has(v) ? v : url;
}
